"""lego_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +y from 12 extrusion(s) and 14 cut(s), applied in order;
each is an outline in the xz plane between two levels. Units: mm.
Run:  python lego_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = 0.0    # level along y
z1 = 2.3    # level along y
z2 = 8.6    # level along y
z3 = 9.6    # level along y
z4 = 10.3    # level along y
z5 = 11.4    # level along y
hole_d1 = 2.6
hole_d2 = 4.1

DIR = (0, 1, 0)


def P(a, b):
    """Point (x, z) in the sketch plane (y = 0)."""
    return (a, 0, b)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: y 0.0 to 9.6 ------------------------------
outline_1 = cf.wire(
    cf.segment(P(-15.9, -7.9), P(15.9, -7.9)),
    cf.segment(P(15.9, -7.9), P(15.9, 7.9)),
    cf.segment(P(15.9, 7.9), P(-15.9, 7.9)),
    cf.segment(P(-15.9, 7.9), P(-15.9, -7.9)),
)
part = prism(outline_1, z0, z3)

# ---- 2. extrusion: y 9.6 to 11.4 ------------------------------
outline_2 = cf.wire(
    Edge.makeCircle(2.4, P(-12.0, 4.0), DIR),
)
part = part + prism(outline_2, z3, z5)

# ---- 3. extrusion: y 9.6 to 11.4 ------------------------------
outline_3 = cf.wire(
    Edge.makeCircle(2.4, P(-12.0, -4.0), DIR),
)
part = part + prism(outline_3, z3, z5)

# ---- 4. extrusion: y 9.6 to 11.4 ------------------------------
outline_4 = cf.wire(
    Edge.makeCircle(2.4, P(-4.0, -4.0), DIR),
)
part = part + prism(outline_4, z3, z5)

# ---- 5. extrusion: y 9.6 to 11.4 ------------------------------
outline_5 = cf.wire(
    Edge.makeCircle(2.4, P(-4.0, 4.0), DIR),
)
part = part + prism(outline_5, z3, z5)

# ---- 6. extrusion: y 9.6 to 11.4 ------------------------------
outline_6 = cf.wire(
    Edge.makeCircle(2.4, P(4.0, 4.0), DIR),
)
part = part + prism(outline_6, z3, z5)

# ---- 7. extrusion: y 9.6 to 11.4 ------------------------------
outline_7 = cf.wire(
    Edge.makeCircle(2.4, P(4.0, -4.0), DIR),
)
part = part + prism(outline_7, z3, z5)

# ---- 8. extrusion: y 9.6 to 11.4 ------------------------------
outline_8 = cf.wire(
    Edge.makeCircle(2.4, P(12.0, -4.0), DIR),
)
part = part + prism(outline_8, z3, z5)

# ---- 9. extrusion: y 9.6 to 11.4 ------------------------------
outline_9 = cf.wire(
    Edge.makeCircle(2.4, P(12.0, 4.0), DIR),
)
part = part + prism(outline_9, z3, z5)

# ---- 10. cut: y 0.0 to 2.3 ------------------------------
count_10 = 3                  # the period repeats 3 times, each moved by step_10
step_10 = Vector(*P(-8.0, 0.0))
period_10 = [
    cf.segment(P(12.6, -6.7), P(12.6, -6.5)),
    cf.segment(P(12.6, -6.5), P(11.4, -6.5)),
    cf.segment(P(11.4, -6.5), P(11.4, -6.7)),
    cf.segment(P(11.4, -6.7), P(4.6, -6.7)),
]
rest_10 = [                     # the outline after the last copy, back to the start
    cf.segment(P(-11.4, -6.7), P(-11.4, -6.5)),
    cf.segment(P(-11.4, -6.5), P(-12.6, -6.5)),
    cf.segment(P(-12.6, -6.5), P(-12.6, -6.7)),
    cf.segment(P(-12.6, -6.7), P(-14.7, -6.7)),
    cf.segment(P(-14.7, -6.7), P(-14.7, -4.6)),
    cf.segment(P(-14.7, -4.6), P(-14.5, -4.6)),
    cf.segment(P(-14.5, -4.6), P(-14.5, -3.4)),
    cf.segment(P(-14.5, -3.4), P(-14.7, -3.4)),
    cf.segment(P(-14.7, -3.4), P(-14.7, 3.4)),
    cf.segment(P(-14.7, 3.4), P(-14.5, 3.4)),
    cf.segment(P(-14.5, 3.4), P(-14.5, 4.6)),
    cf.segment(P(-14.5, 4.6), P(-14.7, 4.6)),
    cf.segment(P(-14.7, 4.6), P(-14.7, 6.7)),
    cf.segment(P(-14.7, 6.7), P(-12.6, 6.7)),
    cf.segment(P(-12.6, 6.7), P(-12.6, 6.5)),
    cf.segment(P(-12.6, 6.5), P(-11.4, 6.5)),
    cf.segment(P(-11.4, 6.5), P(-11.4, 6.7)),
    cf.segment(P(-11.4, 6.7), P(-4.6, 6.7)),
    cf.segment(P(-4.6, 6.7), P(-4.6, 6.5)),
    cf.segment(P(-4.6, 6.5), P(-3.4, 6.5)),
    cf.segment(P(-3.4, 6.5), P(-3.4, 6.7)),
    cf.segment(P(-3.4, 6.7), P(3.4, 6.7)),
    cf.segment(P(3.4, 6.7), P(3.4, 6.5)),
    cf.segment(P(3.4, 6.5), P(4.6, 6.5)),
    cf.segment(P(4.6, 6.5), P(4.6, 6.7)),
    cf.segment(P(4.6, 6.7), P(11.4, 6.7)),
    cf.segment(P(11.4, 6.7), P(11.4, 6.5)),
    cf.segment(P(11.4, 6.5), P(12.6, 6.5)),
    cf.segment(P(12.6, 6.5), P(12.6, 6.7)),
    cf.segment(P(12.6, 6.7), P(14.7, 6.7)),
    cf.segment(P(14.7, 6.7), P(14.7, 4.6)),
    cf.segment(P(14.7, 4.6), P(14.5, 4.6)),
    cf.segment(P(14.5, 4.6), P(14.5, 3.4)),
    cf.segment(P(14.5, 3.4), P(14.7, 3.4)),
    cf.segment(P(14.7, 3.4), P(14.7, -3.4)),
    cf.segment(P(14.7, -3.4), P(14.5, -3.4)),
    cf.segment(P(14.5, -3.4), P(14.5, -4.6)),
    cf.segment(P(14.5, -4.6), P(14.7, -4.6)),
    cf.segment(P(14.7, -4.6), P(14.7, -6.7)),
    cf.segment(P(14.7, -6.7), P(12.6, -6.7)),
]
outline_10 = cf.wire(*[e.translate(step_10 * m) for m in range(count_10) for e in period_10], *rest_10)
part = part - prism(outline_10, z0, z1)

# ---- 11. cut: y 2.3 to 8.6 ------------------------------
outline_11 = cf.wire(
    cf.segment(P(-14.7, -3.4), P(-14.7, 3.4)),
    cf.segment(P(-14.7, 3.4), P(-14.5, 3.4)),
    cf.segment(P(-14.5, 3.4), P(-14.5, 4.6)),
    cf.segment(P(-14.5, 4.6), P(-14.7, 4.6)),
    cf.segment(P(-14.7, 4.6), P(-14.7, 6.7)),
    cf.segment(P(-14.7, 6.7), P(-12.6, 6.7)),
    cf.segment(P(-12.6, 6.7), P(-12.6, 6.5)),
    cf.segment(P(-12.6, 6.5), P(-11.4, 6.5)),
    cf.segment(P(-11.4, 6.5), P(-11.4, 6.7)),
    cf.segment(P(-11.4, 6.7), P(-4.6, 6.7)),
    cf.segment(P(-4.6, 6.7), P(-4.6, 6.5)),
    cf.segment(P(-4.6, 6.5), P(-3.4, 6.5)),
    cf.segment(P(-3.4, 6.5), P(-3.4, 6.7)),
    cf.segment(P(-3.4, 6.7), P(-0.55, 6.7)),
    cf.segment(P(-0.55, 6.7), P(-0.55, 3.2031)),
    Edge.makeThreePointArc(P(-0.55, 3.2031), P(-3.25, 0.0), P(-0.55, -3.2031)),
    cf.segment(P(-0.55, -3.2031), P(-0.55, -6.7)),
    cf.segment(P(-0.55, -6.7), P(-3.4, -6.7)),
    cf.segment(P(-3.4, -6.7), P(-3.4, -6.5)),
    cf.segment(P(-3.4, -6.5), P(-4.6, -6.5)),
    cf.segment(P(-4.6, -6.5), P(-4.6, -6.7)),
    cf.segment(P(-4.6, -6.7), P(-11.4, -6.7)),
    cf.segment(P(-11.4, -6.7), P(-11.4, -6.5)),
    cf.segment(P(-11.4, -6.5), P(-12.6, -6.5)),
    cf.segment(P(-12.6, -6.5), P(-12.6, -6.7)),
    cf.segment(P(-12.6, -6.7), P(-14.7, -6.7)),
    cf.segment(P(-14.7, -6.7), P(-14.7, -4.6)),
    cf.segment(P(-14.7, -4.6), P(-14.5, -4.6)),
    cf.segment(P(-14.5, -4.6), P(-14.5, -3.4)),
    cf.segment(P(-14.5, -3.4), P(-14.7, -3.4)),
)
part = part - prism(outline_11, z1, z2)

# ---- 12. cut: y 2.3 to 8.6 ------------------------------
outline_12 = cf.wire(
    cf.segment(P(14.7, -3.4), P(14.7, 3.4)),
    cf.segment(P(14.7, 3.4), P(14.5, 3.4)),
    cf.segment(P(14.5, 3.4), P(14.5, 4.6)),
    cf.segment(P(14.5, 4.6), P(14.7, 4.6)),
    cf.segment(P(14.7, 4.6), P(14.7, 6.7)),
    cf.segment(P(14.7, 6.7), P(12.6, 6.7)),
    cf.segment(P(12.6, 6.7), P(12.6, 6.5)),
    cf.segment(P(12.6, 6.5), P(11.4, 6.5)),
    cf.segment(P(11.4, 6.5), P(11.4, 6.7)),
    cf.segment(P(11.4, 6.7), P(4.6, 6.7)),
    cf.segment(P(4.6, 6.7), P(4.6, 6.5)),
    cf.segment(P(4.6, 6.5), P(3.4, 6.5)),
    cf.segment(P(3.4, 6.5), P(3.4, 6.7)),
    cf.segment(P(3.4, 6.7), P(0.55, 6.7)),
    cf.segment(P(0.55, 6.7), P(0.55, 3.2031)),
    Edge.makeThreePointArc(P(0.55, 3.2031), P(3.25, 0.0), P(0.55, -3.2031)),
    cf.segment(P(0.55, -3.2031), P(0.55, -6.7)),
    cf.segment(P(0.55, -6.7), P(3.4, -6.7)),
    cf.segment(P(3.4, -6.7), P(3.4, -6.5)),
    cf.segment(P(3.4, -6.5), P(4.6, -6.5)),
    cf.segment(P(4.6, -6.5), P(4.6, -6.7)),
    cf.segment(P(4.6, -6.7), P(11.4, -6.7)),
    cf.segment(P(11.4, -6.7), P(11.4, -6.5)),
    cf.segment(P(11.4, -6.5), P(12.6, -6.5)),
    cf.segment(P(12.6, -6.5), P(12.6, -6.7)),
    cf.segment(P(12.6, -6.7), P(14.7, -6.7)),
    cf.segment(P(14.7, -6.7), P(14.7, -4.6)),
    cf.segment(P(14.7, -4.6), P(14.5, -4.6)),
    cf.segment(P(14.5, -4.6), P(14.5, -3.4)),
    cf.segment(P(14.5, -3.4), P(14.7, -3.4)),
)
part = part - prism(outline_12, z1, z2)

# ---- round holes: (x, z, diameter, from, to) ------------------------
for a, b, d, lo, hi in [
    (12.0, 4.0, hole_d1, z2, z4),
    (12.0, -4.0, hole_d1, z2, z4),
    (4.0, -4.0, hole_d1, z2, z4),
    (4.0, 4.0, hole_d1, z2, z4),
    (-4.0, 4.0, hole_d1, z2, z4),
    (-4.0, -4.0, hole_d1, z2, z4),
    (-12.0, -4.0, hole_d1, z2, z4),
    (-12.0, 4.0, hole_d1, z2, z4),
]:
    part = part - hole(a, b, d, lo, hi)

# ---- 13. extrusion: y 0.0 to 8.6 ------------------------------
outline_13 = cf.wire(
    Edge.makeCircle(3.25, P(8.0, 0.0), DIR),
)
part = part + prism(outline_13, z0, z2)

# ---- 14. extrusion: y 0.0 to 2.3 ------------------------------
outline_14 = cf.wire(
    Edge.makeCircle(3.25, P(0.0, 0.0), DIR),
)
part = part + prism(outline_14, z0, z1)

# ---- 15. extrusion: y 0.0 to 8.6 ------------------------------
outline_15 = cf.wire(
    Edge.makeCircle(3.25, P(-8.0, 0.0), DIR),
)
part = part + prism(outline_15, z0, z2)

# ---- round holes: (x, z, diameter, from, to) ------------------------
for a, b, d, lo, hi in [
    (8.0, 0.0, hole_d2, z0, z2),
    (0.0, 0.0, hole_d2, z0, z2),
    (-8.0, 0.0, hole_d2, z0, z2),
]:
    part = part - hole(a, b, d, lo, hi)

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "lego_exact.step")
